CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS habits (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, cadence text NOT NULL CHECK(cadence IN ('daily','weekly')), target_per_week integer NOT NULL CHECK(target_per_week BETWEEN 1 AND 7), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS goals (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL, metric text NOT NULL CHECK(metric IN ('manual','account_balance','activity_minutes','habit_completions','tasks_completed')), target bigint NOT NULL CHECK(target>0), manual_progress bigint NOT NULL DEFAULT 0 CHECK(manual_progress>=0), linked_account_id uuid, linked_habit_id uuid, due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(linked_account_id,user_id) REFERENCES accounts(id,user_id), FOREIGN KEY(linked_habit_id,user_id) REFERENCES habits(id,user_id));
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, project_id uuid, goal_id uuid, title text NOT NULL, notes text NOT NULL DEFAULT '', priority text NOT NULL CHECK(priority IN ('low','medium','high')), due_at timestamptz, reminder_at timestamptz, recurrence text NOT NULL CHECK(recurrence IN ('none','daily','weekly','monthly')), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(project_id,user_id) REFERENCES projects(id,user_id), FOREIGN KEY(goal_id,user_id) REFERENCES goals(id,user_id));
CREATE TABLE IF NOT EXISTS habit_logs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, habit_id uuid NOT NULL, occurred_on date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(habit_id,user_id) REFERENCES habits(id,user_id) ON DELETE CASCADE, UNIQUE(user_id,habit_id,occurred_on));
ALTER TABLE activities ADD COLUMN IF NOT EXISTS goal_id uuid;
CREATE TABLE IF NOT EXISTS imports (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, source text NOT NULL CHECK(source IN ('bank_csv','calendar_csv','fitness_csv')), name text NOT NULL, status text NOT NULL DEFAULT 'completed', record_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS import_id uuid;
ALTER TABLE activities ADD COLUMN IF NOT EXISTS import_id uuid;
CREATE TABLE IF NOT EXISTS ai_query_logs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, question text NOT NULL, answer text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS ai_consent boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS tasks_user_due ON tasks(user_id,due_at);
CREATE INDEX IF NOT EXISTS habit_logs_user_date ON habit_logs(user_id,occurred_on);
CREATE INDEX IF NOT EXISTS imports_user_date ON imports(user_id,created_at);
